SELECT row_number() OVER (ORDER BY d.n, c.recall_number COLLATE "C"), d.n, c.recall_number, 'Class ' || c.classification, to_char(c.report_date, 'MM/DD/YYYY'), coalesce((SELECT a.name FROM h2.organization__aliases a WHERE a.owner_iri = c.recalling_firm_iri ORDER BY a.name LIMIT 1), (SELECT o.name FROM h2.organization o WHERE o.iri = c.recalling_firm_iri)) FROM h2.recall c CROSS JOIN (VALUES (1), (2)) AS d(n) WHERE d.n = 1 OR get_byte(decode(md5(c.recall_number), 'hex'), 0) % 10 = 0;
